INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(48411, 'Deuteronomy 20:14', 'Deuteronomy', 20, 14, 'خو تاسو کولای شئ چې د هغه ښار ښځې، ماشومان، حیوانات او نور ټول شیان د غنیمت په توګه د ځان دپاره واخلئ. تاسو کولای شئ چې د خپلو دښمنانو هر شی وکاروئ. څښتن هغه تاسو ته درکړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_14.mp3', '', 1761754199, 1761754199),
(48412, 'Deuteronomy 20:15', 'Deuteronomy', 20, 15, 'تاسو باید د هغو ښارونو سره چې د وعده شوې ځمکې څخه لېرې دي همداسې چلند وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_15.mp3', '', 1761754199, 1761754199),
(48413, 'Deuteronomy 20:16', 'Deuteronomy', 20, 16, 'خو کله چې تاسو په هغه خاوره کې چې خپل څښتن خدای یې درکوي، ښارونه ونیسئ، نو د هغه ځای ټول خلک او حیوانات ووژنئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_16.mp3', '', 1761754199, 1761754199),
(48414, 'Deuteronomy 20:17', 'Deuteronomy', 20, 17, 'د څښتن د حکم له مخې ټول خلک په پوره توګه له منځه یوسئ یعنې حیتیان، اموریان، کنعانیان، فرزیان، حویان او یبوسیان.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_17.mp3', '', 1761754199, 1761754199),
(48415, 'Deuteronomy 20:18', 'Deuteronomy', 20, 18, 'هغوی ووژنئ، ترڅو په تاسو باندې د هغو ټولو ناوړه شیانو په درزده کولو سره چې هغوی یې خپلو خدایانو ته په عبادت کې کوي، د څښتن په وړاندې ګناه ونه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_18.mp3', '', 1761754199, 1761754199),
(48416, 'Deuteronomy 20:19', 'Deuteronomy', 20, 19, 'کله چې تاسو یو ښار د زیات وخت دپاره تر محاصرې لاندې نیسئ او د هغه په وړاندې جنګېږئ چې ویې نیسئ، نو د هغه ځای د مېوې ونې مه وهئ، ځکه چې تاسو کولای شئ د هغو مېوه وخورئ. ونې یې له منځه مه وړئ، ځکه چې ونې ستاسو دښمنان نه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_19.mp3', '', 1761754199, 1761754199),
(48417, 'Deuteronomy 20:20', 'Deuteronomy', 20, 20, 'کېدای شي چې تاسو د زینو او برجونو د جوړولو دپاره لرګیو ته اړتیا ولرئ چې دېوالونو ته په ختلو او د ښار په نیولو کې درسره مرسته وکړي. خو یوازې د هغو ونو څخه کار واخلئ چې په دې پوهېږئ چې هغه د مېوې ونې نه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_20.mp3', '', 1761754199, 1761754199),
(48418, 'Daniel 1:1', 'Daniel', 1, 1, 'د يهوداه د بادشاه د يهويقيم د حکومت په درېم کال، د بابل بادشاه نبوکدنضر يروشلم ته راغلو او هغه يې محاصره کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_1.mp3', '', 1761754199, 1761754199),
(48419, 'Daniel 1:2', 'Daniel', 1, 2, 'او مالِک خُدائ يهويقيم د يهوداه بادشاه سره د خُدائ د کور څۀ خاص څيزونه د هغۀ لاسونو ته حواله کړل. هغۀ دا د خُدائ د کور سامانونه بابل ته د خپل معبود کور ته يوړل او دا يې د خپل معبود د کور په خزانه کښې کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_2.mp3', '', 1761754199, 1761754199),
(48420, 'Daniel 1:3', 'Daniel', 1, 3, 'نو بيا بادشاه د خپل دربار مشر خصى آفسر آشپيناز ته حکم وکړو، چې يو څو بنى اِسرائيليان چې د شاهى خاندان او مخوريزو سړو سره تعلق ساتى راولئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_3.mp3', '', 1761754199, 1761754199),
(48421, 'Daniel 1:4', 'Daniel', 1, 4, 'يو څو ځوانان چې هيڅ قسمه جسمانى عېب په کښې نۀ وى، چې ښکلى، او د هر قسمه زده کړې قابليت په کښې وى، ښۀ هوښيار وى، په پوهېدلو کښې تېز، او د شاهى محل د خِدمت قابل وى راوله. هغه به دې ځوانانو ته د بابل د ژبې او د ادب لوستلو تربيت ورکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_4.mp3', '', 1761754199, 1761754199),
(48422, 'Daniel 1:5', 'Daniel', 1, 5, 'نو بادشاه د خپل دربار د شاهى دسترخوان نه هغوئ ته د خوراک خوړلو او د ميو څښلو حکم ورکړو. دوئ ته به درې کاله تربيت ورکړے شى او د دې نه وروستو به دوئ د بادشاه د خِدمت دپاره حاضر شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_5.mp3', '', 1761754199, 1761754199),
(48423, 'Daniel 1:6', 'Daniel', 1, 6, 'په هغوئ کښې ځينې د يهوداه د قبيلې وُو لکه دانيال، حننياه، ميشائيل او عزرياه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_6.mp3', '', 1761754199, 1761754199),
(48424, 'Daniel 1:7', 'Daniel', 1, 7, 'هغه د خصيانو مشر آفسر په هغوئ نوى نومونه کېښودل، په دانيال يې بيلطشضر، په حننياه يې شدرک، په ميشائيل يې ميشک، او په عزرياه يې عبدنجو نوم کېښودو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_7.mp3', '', 1761754199, 1761754199),
(48425, 'Daniel 1:8', 'Daniel', 1, 8, 'خو دانيال دا فېصله وکړه چې خپل ځان به په شاهى خوراک او شاهى ميو نۀ پليتوى، او هغۀ د خصيانو د مشر آفسر نه اجازت وغوښتو چې هغه په دې طريقې ځان نۀ پليتوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_8.mp3', '', 1761754199, 1761754199),
(48426, 'Daniel 1:9', 'Daniel', 1, 9, 'نو اوس خُدائ پاک د خصيانو د مشر آفسر په زړۀ کښې د دانيال دپاره مينه او رحم واچولو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_9.mp3', '', 1761754199, 1761754199),
(48427, 'Daniel 1:10', 'Daniel', 1, 10, 'خو د خصيانو مشر آفسر دانيال ته ووئيل، ”زۀ د خپل مالِک بادشاه نه يرېږم، چا چې ستاسو خوراک څښاک مقرر کړے دے. او کۀ هغه تاسو د نورو همزولو ځوانانو نه کمزورى وګورى نو بيا به څۀ کيږى؟ نو بادشاه به بيا ستاسو په وجه زما سر پرې کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_10.mp3', '', 1761754199, 1761754199),
(48428, 'Daniel 1:11', 'Daniel', 1, 11, 'دانيال بيا هغه ملازم ته وفرمائيل کوم چې د خصيانو مشر آفسر په دانيال، حننياه، ميشائيل او عزرياه مقرر کړے وو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_11.mp3', '', 1761754199, 1761754199),
(48429, 'Daniel 1:12', 'Daniel', 1, 12, '”مهربانى وکړئ تاسو د خپلو نوکرانو د لسو ورځو دپاره اندازه واخلئ، او مونږ ته د خوراک دپاره سبزۍ او د څښلو دپاره د اوبو نه بغېر بل څۀ مۀ راکوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_12.mp3', '', 1761754199, 1761754199),
(48430, 'Daniel 1:13', 'Daniel', 1, 13, 'نو بيا زمونږ شکلونه د هغه ځوانانو سره وګوره څوک چې شاهى خوراک څښاک کوى، او بيا د خپلو نوکرانو سره هغه شان وکړه څۀ چې تۀ ګورې.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_13.mp3', '', 1761754199, 1761754199),
(48431, 'Daniel 1:14', 'Daniel', 1, 14, 'نو هغه بيا دې خبرې ته راضى شو او لس ورځې يې د هغوئ اندازه واخستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_14.mp3', '', 1761754199, 1761754199),
(48432, 'Daniel 1:15', 'Daniel', 1, 15, 'د لسو ورځو په آخر کښې هغوئ د نورو ټولو ځوانانو نه صحتمند او ښۀ ښکارېدل چا چې شاهى خوراک کولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_15.mp3', '', 1761754199, 1761754199),
(48433, 'Daniel 1:16', 'Daniel', 1, 16, 'نو بيا هغه ملازم د هغوئ نه مقرر شوے خوراک او مے اخوا کړل او د هغې په ځائ يې سبزى ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_16.mp3', '', 1761754199, 1761754199),
(48434, 'Daniel 1:17', 'Daniel', 1, 17, 'نو دې څلورو واړو ځوانانو ته خُدائ پاک د هر قسم ادب، عِلم، پوهه او زده کړه ورکړه، او دانيال هم د هر قسم رويا او خوبونو تعبير کولے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_17.mp3', '', 1761754199, 1761754199),
(48435, 'Daniel 1:18', 'Daniel', 1, 18, 'کوم وخت چې بادشاه د هغوئ د تربيت دپاره مقرر کړے وو پوره شو، نو بيا د خصيانو مشر آفسر هغه ټول ځوانان نبوکدنضر ته پېش کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_18.mp3', '', 1761754199, 1761754199),
(48436, 'Daniel 1:19', 'Daniel', 1, 19, 'بادشاه د هغوئ سره خبرې وکړې، او هغۀ يو کس هم په دوئ کښې د دانيال، حننياه، ميشائيل او عزرياه برابر پېدا نۀ کړو، نو هغوئ د بادشاه په دربار کښې په خِدمت کولو مقرر شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_19.mp3', '', 1761754199, 1761754199),
(48437, 'Daniel 1:20', 'Daniel', 1, 20, 'بادشاه د عقل او پوهې په هره مسئله کښې به چې کله د هغوئ نه تپوس کولو، نو هغۀ هغوئ د خپل سلطنت د ټولو جادوګرو او نجوميانو نه لس چنده هوښيار بياموندل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_20.mp3', '', 1761754199, 1761754199),
(48438, 'Daniel 1:21', 'Daniel', 1, 21, 'او دانيال د فارس د خورس د بادشاهۍ اول کال پورې هلته په شاهى دربار کښې خِدمت کولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel1_verse_21.mp3', '', 1761754199, 1761754199),
(48439, 'Jeremiah 35:1', 'Jeremiah', 35, 1, 'د مالِک خُدائ پېغام يرمياه ته د يهويقيم د يوسياه د زوئ د حکومت په دوران کښې ورکړے شو او هغۀ ته يې وفرمائيل چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_1.mp3', '', 1761754199, 1761754199),
(48440, 'Jeremiah 35:2', 'Jeremiah', 35, 2, '”د ريکاب خاندان ته لاړ شه او هغوئ ته دعوت ورکړه چې د مالِک خُدائ کور ته راشى نو بيا هغوئ هلته يوې کوټې ته بوځه او د څښلو دپاره ورله مے ورکړه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_2.mp3', '', 1761754199, 1761754199),
(48441, 'Jeremiah 35:3', 'Jeremiah', 35, 3, 'نو بيا زۀ يازنياه د يرمياه زوئ او د حبصنيا نمسى ته او د هغۀ زامنو او وروڼو او د ريکاب مکمل خاندان ته ورغلم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_3.mp3', '', 1761754199, 1761754199),
(48442, 'Jeremiah 35:4', 'Jeremiah', 35, 4, 'ما هغوئ ټول د مالِک خُدائ کور ته او د يجدليا د زوئ حنان پېغمبر او د هغۀ د زامنو کوټې ته راوستل چې د خُدائ پاک خادِم وو. دا کوټه د آفسرانو د کوټې سره خوا کښې او د معسياه د سلوم زوئ چې چوکيدار وو د هغۀ د کوټې دپاسه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_4.mp3', '', 1761754199, 1761754199),
(48443, 'Jeremiah 35:5', 'Jeremiah', 35, 5, 'نو بيا ما جامونه سره د پيالو راواخستل او د ميو نه مې ډک کړل او هغه مې د ريکاب خاندان ته پېش کړل او ورته مې ووئيل چې، ”راشئ او مے وڅښئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_5.mp3', '', 1761754199, 1761754199),
(48444, 'Jeremiah 35:6', 'Jeremiah', 35, 6, 'خو هغوئ راته په جواب کښې ووئيل چې، ”مونږ مے نۀ څښو، ځکه چې زمونږ نيکۀ يوندب د ريکاب زوئ مونږ ته دا حکم راکړے دے چې تاسو او ستاسو اولاد دې کله هم مے نۀ څښى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_6.mp3', '', 1761754199, 1761754199),
(48445, 'Jeremiah 35:7', 'Jeremiah', 35, 7, 'او تاسو کورونه مۀ جوړَوئ، او تخم مۀ کَرئ، او مۀ د انګورو باغونه کَرئ او تاسو چې هيڅکله دا کارونه ونۀ کړئ، او ضرورى ده چې په خپلو خېمو کښې اوسېږئ. نو بيا به تاسو په هغه زمکه تر ډېره وخته پورې ژوندى پاتې شئ چرته چې تاسو د مسافرو په شان ژوند کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_7.mp3', '', 1761754199, 1761754199),
(48446, 'Jeremiah 35:8', 'Jeremiah', 35, 8, 'مونږ د هغه هر څۀ تابع يُو د څۀ چې مونږ ته زمونږ نيکۀ يوندب د ريکاب زوئ تعليم راکړے دے. نۀ خو مونږ او نۀ زمونږ ښځو او نۀ زمونږ زامنو لوڼو کله مے څښلى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_8.mp3', '', 1761754199, 1761754199),
(48447, 'Jeremiah 35:9', 'Jeremiah', 35, 9, 'او نۀ مونږ د اوسېدو دپاره کورونه جوړ کړى او نۀ مو د انګور باغ، پټى يا فصلونه کَرلى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_9.mp3', '', 1761754199, 1761754199),
(48448, 'Jeremiah 35:10', 'Jeremiah', 35, 10, 'مونږ په خېمو کښې اوسېدلو او په هر هغه څۀ مو پوره عمل کړے دے څۀ چې مونږ ته زمونږ نيکۀ يوندب حکم کړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_10.mp3', '', 1761754199, 1761754199),
(48449, 'Jeremiah 35:11', 'Jeremiah', 35, 11, 'خو کله چې نبوکدنضر بادشاه په دې مُلک باندې قبضه وکړه، مونږ ووئيل، راځئ چې، مونږ يروشلم ته د بابليانو او د شام د لښکرو نه وتښتُو. نو بيا ځکه مونږ په يروشلم کښې پاتې شُو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_11.mp3', '', 1761754199, 1761754199),
(48450, 'Jeremiah 35:12', 'Jeremiah', 35, 12, 'نو بيا د مالِک خُدائ کلام په يرمياه نازل شو، او وې فرمائيل چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_12.mp3', '', 1761754199, 1761754199),
(48451, 'Jeremiah 35:13', 'Jeremiah', 35, 13, '”دا هغه کلام دے چې مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، لاړ شه او د يهوداه سړو او د يروشلم خلقو ته ووايه چې، آيا تاسو د دې نه سبق نۀ زده کوئ او زما د کلام پيروى نۀ کوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_13.mp3', '', 1761754199, 1761754199),
(48452, 'Jeremiah 35:14', 'Jeremiah', 35, 14, 'يوندب د ريکاب زوئ خپلو بچو ته حکم وکړو چې مے مۀ څښئ نو هغوئ د هغۀ دا حکم ومنلو. تر نن ورځ پورې چا هم په هغوئ کښې مے ونۀ څښل، ځکه چې هغوئ د خپل پلار نيکۀ د حکم پيروى کوى. خو ما تاسو سره په څو څو ځله خبرې وکړې خو تاسو زما د خبرو پيروى ونۀ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_14.mp3', '', 1761754199, 1761754199),
(48453, 'Jeremiah 35:15', 'Jeremiah', 35, 15, 'ما تاسو ته بار بار خپل نبيان درولېږل. هغوئ تاسو ته وفرمائيل چې، په تاسو کښې دې هر يو د خپلو بدو کارونو نه واوړى او ښۀ کارونه دې کوى، او مۀ تاسو د نورو معبودانو پيروى کوئ او مۀ يې خِدمت کوئ. نو بيا به تاسو په هغه زمکه کښې اوسېږئ کومه چې ما ستاسو پلار نيکۀ ته ورکړې ده. خو تاسو زما خبرو ته توجو ورنۀ کړه او نۀ مو غوږ ونيولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_15.mp3', '', 1761754199, 1761754199),
(48454, 'Jeremiah 35:16', 'Jeremiah', 35, 16, 'يوندب چې د ريکاب زوئ د هغۀ اولاد د خپل پلار حُکم ومنلو او د هغې پيروى يې وکړه، خو تاسو خلقو زما خبره ونۀ منله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_16.mp3', '', 1761754199, 1761754199),
(48455, 'Jeremiah 35:17', 'Jeremiah', 35, 17, 'نو د دې په وجه مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، ما ته غوږ شئ‎. زۀ اوس د يهوداه او د يروشلم په ټولو خلقو باندې هغه ټول افتونه راولم د کومو چې ما د هغوئ خلاف اعلان کړے دے. ما هغوئ ته ووئيل، خو هغوئ غوږ ونۀ نيولو. ما هغوئ ته آواز وکړو، خو هغوئ ما ته جواب رانۀ کړو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_17.mp3', '', 1761754199, 1761754199),
(48456, 'Jeremiah 35:18', 'Jeremiah', 35, 18, 'نو يرمياه د ريکاب خاندان ته وفرمائيل، ”مالِک خُدائ، ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، تاسو خو د خپل پلار نيکۀ يوندب حکم ومنلو او د هغۀ د ټولو هداياتو مو تابعدارى وکړه او په هر هغه څۀ باندې مو عمل وکړو چې هغۀ درته وئيلى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_18.mp3', '', 1761754199, 1761754199),
(48457, 'Jeremiah 35:19', 'Jeremiah', 35, 19, 'نو په دې وجه مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، د يوندب د ريکاب د زوئ په خاندان کښې به همېشه يو سړے داسې وى چې زما خِدمت به کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah35_verse_19.mp3', '', 1761754199, 1761754199),
(48458, 'Deuteronomy 17:1', 'Deuteronomy', 17, 1, 'خپل څښتن خدای ته داسې غویی او پسه مه قرباني کوئ چې کوم عیب په کې وي، څښتن د دې کار څخه کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_1.mp3', '', 1761754199, 1761754199),
(48459, 'Deuteronomy 17:4', 'Deuteronomy', 17, 4, 'که چېرې تاسو داسې خبر واورئ، نو د هغې په هکله پوره څېړنه وکړئ. که چېرې دا خبره رښتیا وي چې په اسراییلو کې داسې د کرکې وړ کار شوی دی،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_4.mp3', '', 1761754199, 1761754199),
(48460, 'Deuteronomy 17:5', 'Deuteronomy', 17, 5, 'نو بیا هغه کس د ښار څخه دباندې بوځئ او سنګسار یې کړئ چې مړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_5.mp3', '', 1761754199, 1761754199),
(48461, 'Deuteronomy 17:6', 'Deuteronomy', 17, 6, 'خو بیاهم هغه دې یوازې په هغه حالت کې ووژل شي چې دوه یا درې شاهدان د هغه په خلاف شاهدي ورکړي. که چېرې یوازې یو شاهد وي، هغه دې نه وژل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_6.mp3', '', 1761754199, 1761754199),
(48462, 'Deuteronomy 17:7', 'Deuteronomy', 17, 7, 'لومړی باید شاهدان تیږې ګوزارې کړي او بیا دې نور ټول خلک هغه کس سنګسار کړي. په دې ډول به تاسو د دې بدکارۍ څخه خلاص شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_7.mp3', '', 1761754199, 1761754199),
(48463, 'Deuteronomy 17:8', 'Deuteronomy', 17, 8, 'کېدای شي چې داسې دعوې وي چې د محلي قاضیانو دپاره یې پرېکړه کول ډېر ګران وي، لکه د جایداد د حقونو یا د چا د ټپي کولو دعوې یا داسې دعوې چې د قتل او د داسې مرګ ترمنځ فرق په کې شامل وي چې په سهوې سره شوی وي. کله چې داسې کار کیږي، نو د عبادت هغه ځای ته لاړ شئ چې ستاسو د څښتن خدای له خوا ټاکل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_8.mp3', '', 1761754199, 1761754199),
(48464, 'Deuteronomy 17:9', 'Deuteronomy', 17, 9, 'نو خپله دعوه لاوي کاهنانو او د هغه وخت قاضي ته وړاندې کړئ او هغوی پرېږدئ چې د دعوې پرېکړه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_9.mp3', '', 1761754199, 1761754199),
(48465, 'Deuteronomy 17:10', 'Deuteronomy', 17, 10, 'هغوی به خپله پرېکړه واوروي او تاسو باید کټ مټ هماغسې وکړئ څنګه چې هغوی یې درته وایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_10.mp3', '', 1761754199, 1761754199),
(48466, 'Deuteronomy 17:11', 'Deuteronomy', 17, 11, 'د هغوی پرېکړه ومنئ او په لارښوونو باندې یې پوره عمل وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_11.mp3', '', 1761754199, 1761754199),
(48467, 'Deuteronomy 17:12', 'Deuteronomy', 17, 12, 'هرڅوک چې دا جرات وکړي چې د قاضي یا هغه کاهن د امر څخه سرغړونه وکړي چې ستاسو د څښتن خدای خدمت کوي، هغه دې ووژل شي. په دې ډول به تاسو د اسراییلو څخه دا بدکاري لېرې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_12.mp3', '', 1761754199, 1761754199),
(48468, 'Deuteronomy 17:13', 'Deuteronomy', 17, 13, 'بیا به ټول خلک د دې څخه خبر شي او وبه وېریږي او بل هېڅوک به دا جرات ونه کړي چې داسې عمل وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_13.mp3', '', 1761754199, 1761754199),
(48469, 'Deuteronomy 17:14', 'Deuteronomy', 17, 14, 'کله چې تاسو هغه ځمکه ونیسئ چې ستاسو څښتن خدای یې درکوي او هلته اوسېږئ، نو وبه وایئ چې مونږ هم لکه د خپل شاوخوا قومونو په شان پاچا غواړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_14.mp3', '', 1761754199, 1761754199),
(48470, 'Deuteronomy 17:15', 'Deuteronomy', 17, 15, 'ګورئ، کوم سړی چې تاسو د پاچا په توګه غوره کوئ، باید هغه څوک وي چې د څښتن له خوا غوره شوی وي. هغه باید ستاسو د قوم څخه وي. کوم پردی سړی خپل پاچا نه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_15.mp3', '', 1761754199, 1761754199),
(48471, 'Deuteronomy 17:16', 'Deuteronomy', 17, 16, 'د پاچا لښکر باید زیات اسونه ونه لري او هغه باید مصر ته خلک د دې دپاره ونه لېږي چې هلته اسونه په بیه واخلي، ځکه چې څښتن ویلي دي چې د هغه قوم دې هېڅکله هلته بېرته نه ځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_16.mp3', '', 1761754199, 1761754199),
(48472, 'Deuteronomy 17:17', 'Deuteronomy', 17, 17, 'پاچا باید ډېرې ښځې ونه لري، ځکه چې هغوی به هغه ولمسوي چې د څښتن په وړاندې بې وفا شي. په پای کې، پاچا باید د دې هڅه ونه کړي چې په زیاته اندازه سره زر او سپین زر لاسته راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_17.mp3', '', 1761754199, 1761754199),
(48473, 'Deuteronomy 17:18', 'Deuteronomy', 17, 18, 'کله چې هغه پاچا شي، هغه دې د دې قوانینو د نسخې یو نقل جوړ کړي چې اصلي نقل یې د لاوي کاهنانو سره دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_18.mp3', '', 1761754199, 1761754199),
(48474, 'Deuteronomy 17:19', 'Deuteronomy', 17, 19, 'د قوانینو دا نقل دې د هغه سره وي او ټول عمر دې هغه لولي، ترڅو د څښتن درناوی کول زده کړي او په وفادارۍ سره د هغو ټولو امرونو اطاعت وکړي چې په دې قوانینو کې راغلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_19.mp3', '', 1761754199, 1761754199),
(48475, 'Deuteronomy 17:20', 'Deuteronomy', 17, 20, 'په دې کار سره به هغه داسې فکر نه کوي چې هغه د نورو اسراییلیانو په پرتله ښه سړی دی او د څښتن د امرونو څخه به هېڅ سرغړونه نه کوي. بیا به هغه او د هغه اولاده د ډېرو کلونو دپاره په اسراییلو باندې حکومت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy17_verse_20.mp3', '', 1761754199, 1761754199),
(48476, 'Psalms 128:1', 'Psalms', 128, 1, 'بختور دي هغه خلک چې وېریږي له څښتنه او څوک چې روان وي د هغه په لاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms128_verse_1.mp3', '', 1761754199, 1761754199),
(48477, 'Psalms 128:2', 'Psalms', 128, 2, 'ستاسو کار به کړي پوره ضرورتونه ستاسو اوسئ خوشحاله او نېکمرغه به یئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms128_verse_2.mp3', '', 1761754199, 1761754199),
(48478, 'Psalms 128:3', 'Psalms', 128, 3, 'ستا ښځه به ستا کور کې وي لکه د مېوه‌دارو انګورو د تاک په شان او ستا اولادونه به وي د زیتون د ونو په شان وي به راتاو په دسترخوان د ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms128_verse_3.mp3', '', 1761754199, 1761754199),
(48479, 'Psalms 128:4', 'Psalms', 128, 4, 'هغه خلک به بختور وي چې کوي وېره له څښتنه څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms128_verse_4.mp3', '', 1761754199, 1761754199),
(48480, 'Psalms 128:5', 'Psalms', 128, 5, 'له صهیونه دې څښتن برکت درکړي درته چې په ټول ژوند کې دې ته وینې اورشلیم اباد', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms128_verse_5.mp3', '', 1761754199, 1761754199),
(48481, 'Psalms 128:6', 'Psalms', 128, 6, 'او تر هغې دې یې ژوندی چې دې لمسیان ووینې سلامتي دې وي په اسراییلو باندې!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms128_verse_6.mp3', '', 1761754199, 1761754199),
