(48483, 'Psalms 83:2', 'Psalms', 83, 2, 'ګوره! ستا دښمنان دي د بلوا حال کې څوک چې کرکه کوي ستا نه پورته کړي یې دي سرونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_2.mp3', '', 1761754199, 1761754199),
(48484, 'Psalms 83:3', 'Psalms', 83, 3, 'د ستا د قوم په وړاندې پلانونه د ټګۍ جوړوي د هغه ولس په ضد چې لرې ته ورسره مینه دوی د هغوی په وړاندې دسیسې جوړوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_3.mp3', '', 1761754199, 1761754199),
