(48486, 'Psalms 83:5', 'Psalms', 83, 5, 'په خپل پلان کې سره جوړ دي هغوی ستا مقابل کې یې تړون کړی دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_5.mp3', '', 1761754199, 1761754199),
(48487, 'Psalms 83:6', 'Psalms', 83, 6, 'د ادوم او اسماعیلیانو قوم د موآبیانو، هاجریانو قوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_6.mp3', '', 1761754199, 1761754199),
