(48489, 'Psalms 83:8', 'Psalms', 83, 8, 'د آشوریانو ولس هم دی مل شوی د هغوی سره او قوي مټ دی هغوی د اولادې د لوط', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_8.mp3', '', 1761754199, 1761754199),
(48490, 'Psalms 83:9', 'Psalms', 83, 9, 'دوی سره داسې عمل وکړه لکه چې څنګه دې ؤ کړی مدیانیانو سره او د سیسرا او هم یابین سره په غاړه د قیشون د سیند', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_9.mp3', '', 1761754199, 1761754199),
(48491, 'Psalms 83:10', 'Psalms', 83, 10, 'لاړل له منځه په عین‌دور کې دوی شول جسدونه یې په ځمکه لکه د سرې په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_10.mp3', '', 1761754199, 1761754199),
(48492, 'Psalms 83:11', 'Psalms', 83, 11, 'له مشرانو سره یې داسې عمل وکړه لکه چې کړی دې غراب او هم د زیب سره ؤ ته ماتې ورکړه د هغوی ټولو حاکمانو ته لکه چې څنګه دې ورکړې وه زبح او هم صلمونع لره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_11.mp3', '', 1761754199, 1761754199),
