(48494, 'Psalms 83:13', 'Psalms', 83, 13, 'د بوړبوړکۍ په شان یې وشینده ای خدایه لکه د بوسو چې یې باد بادوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_13.mp3', '', 1761754199, 1761754199),
(48495, 'Psalms 83:14', 'Psalms', 83, 14, 'لکه په اور باندې چې سوځي ځنګل لکه لمبو باندې چې سوځي غرونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_14.mp3', '', 1761754199, 1761754199),
(48496, 'Psalms 83:15', 'Psalms', 83, 15, 'په خپل توفان باندې دوی وځغلوه ته هغوی ووېروه خپلو سختو بادونو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_15.mp3', '', 1761754199, 1761754199),
(48497, 'Psalms 83:16', 'Psalms', 83, 16, 'د دوی مخونه په شرمونو پټ کړه ترڅو تسلیم شي هغوی ای څښتنه ستا قدرت ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_16.mp3', '', 1761754199, 1761754199),
(48498, 'Psalms 83:17', 'Psalms', 83, 17, 'وي دې رسوا هغوی او تل دې په وېره کې وي او په ذلت کې دې هغوی شي هلاک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_17.mp3', '', 1761754199, 1761754199),
(48499, 'Psalms 83:18', 'Psalms', 83, 18, 'هغوی دې پوه شي چې یوازې ته یې چې دې نوم دی څښتن یې خدای تعالی ته د ټولې ځمکې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms83_verse_18.mp3', '', 1761754199, 1761754199),
(48500, 'Exodus 1:6', 'Exodus', 1, 6, 'د وخت په تېرېدلو سره یوسف، د هغه ورونه او د هغې زمانې ټول خلک مړه شول،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus1_verse_6.mp3', '', 1761754199, 1761754199),
(48501, 'Exodus 1:7', 'Exodus', 1, 7, 'خو د هغوی اولاده یعنې اسراییلیان د زیاتو اولادونو خاوندان شول او هغوی دومره زیات شول چې مصر ورڅخه ډک شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus1_verse_7.mp3', '', 1761754199, 1761754199),
(48502, 'Exodus 1:8', 'Exodus', 1, 8, 'له ډېرو کلونو وروسته په مصر کې یو نوي پاچا قدرت تر لاسه کړ چې هغه د یوسف په اړه هېڅ معلومات نه درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus1_verse_8.mp3', '', 1761754199, 1761754199),
(48503, 'Exodus 1:9', 'Exodus', 1, 9, 'هغه مصریانو ته وویل: «د اسراییلو شمېر زمونږ په خاوره کې ډېر شوی دی او هغوی زمونږ نه ډېر قوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus1_verse_9.mp3', '', 1761754199, 1761754199),
(48504, 'Exodus 1:10', 'Exodus', 1, 10, 'که چېرې جنګ وشي، نو کېدای شي چې هغوی زمونږ د دښمنانو سره یوځای شي او زمونږ په وړاندې وجنګیږي او د دې وطن څخه وتښتي. نو مونږ باید کومه لاره چاره وسنجوو او پرېنږدو چې د هغوی شمېر له دې څخه نور هم زیات شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus1_verse_10.mp3', '', 1761754199, 1761754199),
(48505, 'Exodus 1:11', 'Exodus', 1, 11, 'نو مصریانو په اسراییلیانو باندې مشران وټاکل، ترڅو هغوی په سختو کارونو باندې کمزوري کړي. هغوی د فیتوم او رعمسیس ښارونه چې فرعون په کې خپل ګودامونه ساتل، جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus1_verse_11.mp3', '', 1761754199, 1761754199),
(48506, 'Exodus 1:12', 'Exodus', 1, 12, 'که څه هم د اسراییلیانو سره بد چلند کېده، خو د هغوی شمېر زیاتېده او نوره ځمکه یې هم ونیوله. له دې امله مصریانو له هغوی څخه وېره درلودله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus1_verse_12.mp3', '', 1761754199, 1761754199),
(48507, 'Exodus 1:15', 'Exodus', 1, 15, 'بیا فرعون دوه دایې ګانې راوغوښتلې چې شفره او فوعه نومېدلې او هغوی د عبرانۍ ښځو سره د اولاد د زېږولو په وخت کې مرسته کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus1_verse_15.mp3', '', 1761754199, 1761754199),
(48508, 'Exodus 1:16', 'Exodus', 1, 16, 'هغوی ته یې وویل: «که چېرې یوه عبرانۍ ښځه انجلۍ وزېږوي، هغه ژوندۍ پرېږدئ او که چېرې هلک وي، نو ویې وژنئ!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus1_verse_16.mp3', '', 1761754199, 1761754199),
(48509, 'Exodus 1:17', 'Exodus', 1, 17, 'که څه هم فرعون ورته ویلي وو، خو دا ښځې د خدای څخه وېرېدلې او هلکان یې نه وژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus1_verse_17.mp3', '', 1761754199, 1761754199),
(48510, 'Exodus 1:18', 'Exodus', 1, 18, 'فرعون یوځل بیا دا دوه دایې ګانې راوغوښتې او پوښتنه یې ترې وکړه: «تاسو ولې هغه هلکان ژوندي پرېږدئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus1_verse_18.mp3', '', 1761754199, 1761754199);